const body = $json.body || $json;
const events = Array.isArray(body.events) ? body.events : [];
return events
  .filter((event) => event.source?.userId && ['follow', 'message'].includes(event.type))
  .filter((event) => event.type !== 'message' || event.message?.type === 'text')
  .map((event) => ({
    json: {
      eventType: event.type,
      lineUserId: event.source.userId,
      replyToken: event.replyToken,
      messageText: event.message?.text?.trim() || '',
      eventTimestamp: new Date(event.timestamp || Date.now()).toISOString()
    }
  }));

const item = $json || {};
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};

const questions = {
  waiting_parent_name: 'รบกวนขอชื่อคุณพ่อ/คุณแม่ หรือผู้ปกครองที่สะดวกให้ติดต่อกลับหน่อยค่ะ',
  waiting_phone: 'ขอเบอร์โทรที่สะดวกให้ทีมงานติดต่อกลับหน่อยนะคะ',
  waiting_student_name: 'น้องชื่ออะไรคะ จะได้ให้ทีมงานเรียกชื่อน้องถูกค่ะ 😊',
  waiting_student_grade: 'ตอนนี้น้องอยู่ระดับชั้นไหนคะ เช่น ป.4, ป.6 หรือ ม.1',
  waiting_pain_point: 'ตอนนี้อยากให้ eiMaths ช่วยน้องเรื่องไหนเป็นพิเศษคะ\nเช่น ไม่ชอบคณิต, กลัวเลข, ทำโจทย์ไม่ค่อยได้, เรียนไม่ทัน หรืออยากเพิ่มความมั่นใจ',
  waiting_preferred_contact_time: 'คุณพ่อ/คุณแม่สะดวกให้ทีมงานติดต่อกลับช่วงเวลาไหนคะ\nเช่น หลัง 18:00 หรือช่วงเย็นหลังเลิกงาน'
};

function introText() {
  return 'สวัสดีค่ะ 😊 ขอบคุณที่สนใจทดลองเรียนฟรีกับ eiMaths นะคะ\nแอดมินขอข้อมูลนิดนึง เพื่อให้ทีมงานช่วยแนะนำคอร์สที่เหมาะกับน้องได้ค่ะ\n\n' + questions.waiting_parent_name;
}

function normalizeText(value) {
  return String(value || '').trim().replace(/\s+/g, ' ');
}

function cleanPhone(value) {
  return String(value || '').replace(/[^0-9+]/g, '');
}

function looksLikePhone(value) {
  const phone = cleanPhone(value);
  return /^[0-9+]{8,15}$/.test(phone);
}

function isOnlyNumber(value) {
  return /^[0-9+\-\s().]+$/.test(String(value || '').trim());
}

function isWeakAnswer(value) {
  const text = normalizeText(value).toLowerCase();
  if (!text) return true;
  if (/^[.\-_/\\!?…]+$/.test(text)) return true;
  const weakWords = [
    'ครับ', 'ค่ะ', 'คะ', 'จ้า', 'จ๊ะ', 'จ้ะ', 'โอเค', 'ok', 'okay',
    'ได้', 'ได้ค่ะ', 'ได้ครับ', 'ใช่', 'ไม่', 'ไม่รู้', 'ไม่แน่ใจ',
    'อืม', 'อือ', 'เอ่อ', '555', '5555', 'test', 'ทดสอบ'
  ];
  return weakWords.includes(text);
}

function validateParentName(text) {
  const value = normalizeText(text);
  if (isWeakAnswer(value)) {
    return { ok: false, reply: 'ขอชื่อคุณพ่อ/คุณแม่ หรือผู้ปกครองอีกครั้งนะคะ 😊\nเช่น แม่แดง, คุณพ่อนัท หรือคุณแม่ก้อยค่ะ' };
  }
  if (looksLikePhone(value) || isOnlyNumber(value)) {
    return { ok: false, reply: 'เหมือนอันนี้จะเป็นเบอร์โทรค่ะ เดี๋ยวขอชื่อผู้ปกครองก่อนนะคะ\nเช่น แม่แดง หรือคุณพ่อนัทค่ะ' };
  }
  if (value.length > 80) {
    return { ok: false, reply: 'ชื่อยาวไปนิดนึงค่ะ รบกวนพิมพ์เฉพาะชื่อผู้ปกครองที่สะดวกให้ติดต่อกลับนะคะ' };
  }
  return { ok: true, value };
}

function validatePhone(text) {
  const value = cleanPhone(text);
  if (!/^[0-9+]{8,15}$/.test(value)) {
    return { ok: false, reply: 'เบอร์โทรอาจยังไม่ครบค่ะ\nรบกวนพิมพ์เป็นตัวเลขอีกครั้งนะคะ เช่น 0812345678' };
  }
  return { ok: true, value };
}

function validateStudentName(text) {
  const value = normalizeText(text);
  if (isWeakAnswer(value)) {
    return { ok: false, reply: 'ขอชื่อน้องอีกครั้งนะคะ จะเป็นชื่อเล่นก็ได้ค่ะ 😊\nเช่น น้องมีนา, น้องต้น หรือ น้องบี' };
  }
  if (looksLikePhone(value) || isOnlyNumber(value)) {
    return { ok: false, reply: 'อันนี้เหมือนเป็นตัวเลขค่ะ รบกวนพิมพ์ชื่อน้องให้หน่อยนะคะ จะเป็นชื่อเล่นก็ได้ค่ะ 😊' };
  }
  if (value.length > 80) {
    return { ok: false, reply: 'ชื่อน้องยาวไปนิดนึงค่ะ รบกวนพิมพ์เฉพาะชื่อหรือชื่อเล่นของน้องนะคะ' };
  }
  return { ok: true, value };
}

function normalizeGrade(text) {
  const raw = normalizeText(text);
  const compact = raw.toLowerCase().replace(/[\s.]/g, '');

  if (/^(เตรียมอนุบาล|nursery|pre[-]?k)$/.test(compact)) {
    return 'เตรียมอนุบาล';
  }

  let match = compact.match(/^(อ|อนุบาล|k)([1-3])$/i);
  if (match) return `อ.${match[2]}`;

  match = compact.match(/^(ป|ประถม|p)([1-6])$/i);
  if (match) return `ป.${match[2]}`;

  match = compact.match(/^(ม|มัธยม|m)([1-6])$/i);
  if (match) return `ม.${match[2]}`;

  return null;
}

function validateGrade(text) {
  const normalized = normalizeGrade(text);
  if (!normalized) {
    return { ok: false, reply: 'ขอระดับชั้นของน้องอีกครั้งนะคะ 😊\nพิมพ์ได้แบบสั้น ๆ เช่น อ.3, ป.5, ป.6 หรือ ม.1 ค่ะ' };
  }
  return { ok: true, value: normalized };
}

function validatePainPoint(text) {
  const value = normalizeText(text);
  if (isWeakAnswer(value) || value.length < 3) {
    return { ok: false, reply: 'ขอทราบปัญหาหรือเป้าหมายของน้องนิดนึงนะคะ\nเช่น กลัวเลข, ไม่ชอบคณิต, ทำโจทย์ไม่ทัน, เรียนไม่เข้าใจ หรืออยากเพิ่มความมั่นใจค่ะ' };
  }
  if (value.length > 500) {
    return { ok: false, reply: 'รายละเอียดค่อนข้างยาวค่ะ รบกวนสรุปสั้น ๆ ว่าอยากให้ช่วยเรื่องไหนเป็นพิเศษนะคะ' };
  }
  return { ok: true, value };
}

function validatePreferredContactTime(text) {
  const value = normalizeText(text);
  if (isWeakAnswer(value)) {
    return { ok: false, reply: 'รบกวนแจ้งช่วงเวลาที่สะดวกให้ทีมงานติดต่อกลับหน่อยนะคะ\nเช่น วันนี้หลัง 18:00, พรุ่งนี้ช่วงเย็น หรือเสาร์-อาทิตย์ค่ะ' };
  }

  const timeLike = /(\d{1,2}[:.]?\d{0,2}|เช้า|สาย|เที่ยง|กลางวัน|บ่าย|เย็น|ค่ำ|กลางคืน|หลัง|ก่อน|วันนี้|พรุ่งนี้|เสาร์|อาทิตย์|ทุกวัน|วันธรรมดา|เลิกงาน|เลิกเรียน|สะดวก)/i;
  if (!timeLike.test(value) || value.length > 200) {
    return { ok: false, reply: 'ขอช่วงเวลาที่สะดวกแบบประมาณก็ได้ค่ะ 😊\nเช่น หลัง 18:00, ช่วงเย็นหลังเลิกงาน หรือเสาร์-อาทิตย์' };
  }
  return { ok: true, value };
}

const now = new Date().toISOString();
const userId = item.lineUserId;
const text = normalizeText(item.messageText || '');
const lowerText = text.toLowerCase();

const restartKeywords = ['เริ่มใหม่', 'ลงทะเบียนใหม่', 'แก้ข้อมูล', 'กรอกใหม่', 'restart', 'reset'];
const isRestartKeyword = restartKeywords.some((keyword) => lowerText.includes(keyword.toLowerCase()));

let conversation = store.conversations[userId] || {
  state: 'waiting_parent_name',
  answers: {},
  createdAt: now,
  followedAt: item.eventType === 'follow' ? now : null,
  startedAt: now,
  lineRef: null,
  handoverReplyCount: 0
};

conversation.displayName = item.displayName || conversation.displayName || null;
conversation.pictureUrl = item.pictureUrl || conversation.pictureUrl || null;
conversation.lastMessageAt = now;
conversation.answers = conversation.answers || {};
if (item.eventType === 'follow' && !conversation.followedAt) conversation.followedAt = now;

// Tracking REF from Laravel /free-trial LINE button.
// Example message: REF:facebook|paid_social|test|-
// This must be stored as campaign tracking only, not consumed as an answer in the chat flow.
const refMatch = text.match(/^REF:([^\s]+)/i);
const isRefMessage = !!refMatch;
if (refMatch) {
  conversation.lineRef = refMatch[1].slice(0, 255);
  conversation.lastRefAt = now;
  conversation.lastRefRaw = text;
}

let replyText = '';
let completed = false;
let shouldReply = true;
let validation = null;

if (isRestartKeyword) {
  conversation.state = 'waiting_parent_name';
  conversation.answers = {};
  conversation.startedAt = now;
  conversation.completedAt = null;
  conversation.handoverReplyCount = 0;
  replyText = 'ได้เลยค่ะ เริ่มลงทะเบียนใหม่ให้นะคะ 😊\n\n' + questions.waiting_parent_name;
} else if (item.eventType === 'follow') {
  conversation.state = 'waiting_parent_name';
  conversation.answers = conversation.answers || {};
  conversation.startedAt = conversation.startedAt || now;
  conversation.handoverReplyCount = 0;
  replyText = introText();
} else if (!text && conversation.state === 'waiting_parent_name') {
  replyText = introText();
} else if (isRefMessage && (conversation.state === 'completed' || conversation.state === 'handover_to_staff')) {
  // User intentionally clicked a tracked LINE registration link again after a previous handover.
  // Start a fresh registration so the new campaign source can be captured.
  conversation.state = 'waiting_parent_name';
  conversation.answers = {};
  conversation.startedAt = now;
  conversation.completedAt = null;
  conversation.handoverReplyCount = 0;
  replyText = introText();
} else if (isRefMessage) {
  // REF is only campaign tracking. Do not save it as parent name, phone, grade, etc.
  if (!questions[conversation.state]) {
    conversation.state = 'waiting_parent_name';
    conversation.answers = {};
    conversation.startedAt = now;
    replyText = introText();
  } else if (conversation.state === 'waiting_parent_name') {
    replyText = introText();
  } else {
    replyText = questions[conversation.state];
  }
} else if (conversation.state === 'waiting_parent_name') {
  validation = validateParentName(text);
  if (!validation.ok) {
    replyText = validation.reply;
  } else {
    conversation.answers.parent_name = validation.value;
    conversation.state = 'waiting_phone';
    replyText = questions.waiting_phone;
  }
} else if (conversation.state === 'waiting_phone') {
  validation = validatePhone(text);
  if (!validation.ok) {
    replyText = validation.reply;
  } else {
    conversation.answers.phone = validation.value;
    conversation.state = 'waiting_student_name';
    replyText = questions.waiting_student_name;
  }
} else if (conversation.state === 'waiting_student_name') {
  validation = validateStudentName(text);
  if (!validation.ok) {
    replyText = validation.reply;
  } else {
    conversation.answers.student_name = validation.value;
    conversation.state = 'waiting_student_grade';
    replyText = questions.waiting_student_grade;
  }
} else if (conversation.state === 'waiting_student_grade') {
  validation = validateGrade(text);
  if (!validation.ok) {
    replyText = validation.reply;
  } else {
    conversation.answers.student_grade = validation.value;
    conversation.state = 'waiting_pain_point';
    replyText = questions.waiting_pain_point;
  }
} else if (conversation.state === 'waiting_pain_point') {
  validation = validatePainPoint(text);
  if (!validation.ok) {
    replyText = validation.reply;
  } else {
    conversation.answers.pain_point = validation.value;
    conversation.state = 'waiting_preferred_contact_time';
    replyText = questions.waiting_preferred_contact_time;
  }
} else if (conversation.state === 'waiting_preferred_contact_time') {
  validation = validatePreferredContactTime(text);
  if (!validation.ok) {
    replyText = validation.reply;
  } else {
    conversation.answers.preferred_contact_time = validation.value;
    conversation.completedAt = now;
    conversation.state = 'handover_to_staff';
    conversation.handoverReplyCount = 0;
    completed = true;
    replyText = 'ขอบคุณมากค่ะ 😊\nแอดมินได้รับข้อมูลเรียบร้อยแล้วนะคะ\n\nเดี๋ยวทีมงาน eiMaths จะติดต่อกลับตามช่วงเวลาที่แจ้งไว้\nเพื่อแนะนำการทดลองเรียนฟรี 2 คลาสให้น้องค่ะ';
  }
} else if (conversation.state === 'completed' || conversation.state === 'handover_to_staff') {
  // เก็บข้อมูลครบและส่งต่อให้ทีมงานแล้ว: ไม่ตอบกลับซ้ำ เพื่อให้ staff คุยต่อได้เป็นธรรมชาติ
  // ถ้าลูกค้าต้องการแก้ข้อมูล ยังสามารถพิมพ์ “เริ่มใหม่” ได้ เพราะถูกจับในเงื่อนไขด้านบนก่อนถึง block นี้
  conversation.state = 'handover_to_staff';
  conversation.handoverReplyCount = Number(conversation.handoverReplyCount || 0) + 1;
  replyText = '';
  shouldReply = false;
} else {
  conversation.state = 'waiting_parent_name';
  conversation.answers = {};
  conversation.startedAt = now;
  conversation.handoverReplyCount = 0;
  replyText = introText();
}

store.conversations[userId] = conversation;

let crmPayload = null;
if (completed) {
  const refParts = String(conversation.lineRef || '').split('|').map((part) => String(part || '').trim());
  const refValue = (index, fallback) => {
    const value = refParts[index];
    return value && value !== '-' ? value : fallback;
  };
  const refContent = refParts[3] && refParts[3] !== '-' ? refParts[3] : null;
  crmPayload = {
    ...conversation.answers,
    interest: 'ทดลองเรียนฟรี 2 คลาส',
    line_user_id: userId,
    line_display_name: conversation.displayName,
    line_picture_url: conversation.pictureUrl,
    line_follow_status: 'followed',
    line_followed_at: conversation.followedAt || now,
    line_last_message_at: now,
    line_conversation_state: 'completed',
    line_ref: conversation.lineRef,
    line_source: 'new_customer_line_oa',
    utm_source: refValue(0, 'line'),
    utm_medium: refValue(1, 'new_customer_oa_chat'),
    utm_campaign: refValue(2, 'unknown'),
    utm_content: refContent,
    first_touch_source: refValue(0, 'line'),
    last_touch_source: 'new_customer_line_oa',
    created_from: 'new_customer_line_oa_chatbot',
    lead_status: 'new_lead'
  };
}

return {
  json: {
    ...item,
    completed,
    replyToken: item.replyToken,
    replyText,
    shouldReply,
    lineUserId: userId,
    conversationState: conversation.state,
    crmPayload
  }
};

